// ─── File: src/test/java/com/bank/cas/CASDeepDiveTest.java ───
package com.bank.cas;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class CASDeepDiveTest {

    // ═══ CAS success on first try (low contention) ═══
    @Test
    void cas_successFirstTry() {
        AtomicInteger counter = new AtomicInteger(42);
        boolean swapped = counter.compareAndSet(42, 43);
        assertThat(swapped).isTrue();
        assertThat(counter.get()).isEqualTo(43);
    }

    // ═══ CAS failure (value changed by another "thread") ═══
    @Test
    void cas_failure_valueDifferent() {
        AtomicInteger counter = new AtomicInteger(42);
        counter.set(99);  // simulate another thread changing it
        boolean swapped = counter.compareAndSet(42, 43);  // expects 42 but it's 99!
        assertThat(swapped).isFalse();
        assertThat(counter.get()).isEqualTo(99);  // unchanged!
    }

    // ═══ CAS spin loop: retry until success ═══
    @Test
    void cas_spinLoop() {
        AtomicInteger counter = new AtomicInteger(0);
        // Simulate incrementAndGet:
        int prev, next;
        do {
            prev = counter.get();
            next = prev + 1;
        } while (!counter.compareAndSet(prev, next));
        assertThat(counter.get()).isEqualTo(1);
    }

    // ═══ High contention: measure CAS retries ═══
    @Test
    void highContention_manyRetries() throws InterruptedException {
        AtomicLong counter = new AtomicLong(0);
        AtomicLong totalAttempts = new AtomicLong(0);
        int threads = 50;
        int ops = 10_000;
        CountDownLatch latch = new CountDownLatch(threads);

        for (int t = 0; t < threads; t++) {
            new Thread(() -> {
                for (int i = 0; i < ops; i++) {
                    long prev, next;
                    int attempts = 0;
                    do {
                        prev = counter.get();
                        next = prev + 1;
                        attempts++;
                    } while (!counter.compareAndSet(prev, next));
                    totalAttempts.addAndGet(attempts);
                }
                latch.countDown();
            }).start();
        }
        latch.await();

        long expected = (long) threads * ops;
        assertThat(counter.get()).isEqualTo(expected);
        double avgAttempts = (double) totalAttempts.get() / expected;
        System.out.println("Total ops: " + expected + ", Avg CAS attempts per op: " + String.format("%.2f", avgAttempts));
        // Under contention: > 1.0 (multiple retries per op!)
    }

    // ═══ AtomicStampedReference: solves ABA ═══
    @Test
    void atomicStampedReference_solvesABA() {
        AtomicStampedReference<String> ref = new AtomicStampedReference<>("A", 0);

        // Simulate ABA:
        ref.compareAndSet("A", "B", 0, 1);  // A→B, stamp 0→1
        ref.compareAndSet("B", "A", 1, 2);  // B→A, stamp 1→2 (ABA!)

        // Regular CAS would succeed (value is "A" again):
        // But stamped CAS checks stamp too:
        boolean swapped = ref.compareAndSet("A", "C", 0, 3);  // expects stamp 0!
        assertThat(swapped).isFalse();  // stamp is 2, not 0! ABA detected!
    }
}
